-- Migración 8 de 8 — competencias, lote 2 (transversal): 90 competencias nuevas.
-- Requiere las migraciones 1 a 7. Se puede ejecutar más de una vez (no duplica nada).
--
-- QUÉ SE AGREGA
--   90 competencias en 7 áreas: datos y análisis, programación y desarrollo, inteligencia artificial, diseño CAD y BIM,
--   gestión de proyectos, calidad y seguridad, y sistemas empresariales. Cada una con su categoría, su forma de detección y su descripción.
--   Principio de las variantes: solo SINÓNIMOS o nombres equivalentes. Una herramienta relacionada, una versión distinta, un componente o
--   una guía NO cuentan como la competencia (si merece contarse, es una competencia propia).
--   Cambio a una existente: SAP recibe variantes de módulos (SAP MM, PP, PM, FI, ERP, S/4HANA).
--
-- QUÉ NO SE TOCA
--   Ninguna política, permiso ni vista. Las 24 competencias actuales quedan igual (salvo las variantes de SAP). Si una competencia
--   con el mismo código ya existe, se respeta tal como está.

begin;

-- ==== SI YA EJECUTASTE LA VERSIÓN ANTERIOR de esta migración (86 competencias), esto la corrige. Si no, no hace nada. ====
-- Solo toca filas que siguen EXACTAMENTE como las dejó esa versión: si editaste alguna a mano, la respeta.
update public.competencias set nombre = 'Análisis de trabajo seguro (ATS)', area = 'calidad_seguridad', categoria = 'actividad', deteccion = 'auto', descripcion = 'Análisis de los pasos y riesgos de una tarea antes de hacerla.', variantes = array['análisis de trabajo seguro']::text[]
 where slug = 'analisis-trabajo-seguro' and nombre = 'Análisis de trabajo seguro (ATS)' and area = 'calidad_seguridad' and categoria = 'metodologia' and deteccion = 'auto' and descripcion = 'Análisis de los pasos y riesgos de una tarea antes de hacerla.' and variantes = array['análisis de trabajo seguro']::text[];
update public.competencias set nombre = 'CI/CD', area = 'programacion', categoria = 'metodologia', deteccion = 'auto', descripcion = 'Integración, entrega y despliegue continuos automatizados (etapas distintas del mismo ciclo).', variantes = array['integración continua', 'despliegue continuo', 'entrega continua']::text[]
 where slug = 'ci-cd' and nombre = 'CI/CD' and area = 'programacion' and categoria = 'metodologia' and deteccion = 'auto' and descripcion = 'Integración y entrega continuas automatizadas.' and variantes = array['integración continua', 'despliegue continuo', 'entrega continua']::text[];
update public.competencias set nombre = 'Git', area = 'programacion', categoria = 'herramienta', deteccion = 'auto', descripcion = 'Sistema de control de versiones distribuido.', variantes = '{}'::text[]
 where slug = 'git' and nombre = 'Git y GitHub' and area = 'programacion' and categoria = 'herramienta' and deteccion = 'auto' and descripcion = 'Control de versiones y trabajo colaborativo con repositorios.' and variantes = array['Git', 'GitHub']::text[];
update public.competencias set nombre = 'IPERC', area = 'calidad_seguridad', categoria = 'actividad', deteccion = 'auto', descripcion = 'Identificación de peligros, evaluación de riesgos y controles.', variantes = array['matriz IPERC', 'identificación de peligros y evaluación de riesgos']::text[]
 where slug = 'iperc' and nombre = 'IPERC' and area = 'calidad_seguridad' and categoria = 'metodologia' and deteccion = 'auto' and descripcion = 'Identificación de peligros, evaluación de riesgos y controles.' and variantes = array['matriz IPERC', 'identificación de peligros y evaluación de riesgos']::text[];
update public.competencias set nombre = 'ISO 14001', area = 'calidad_seguridad', categoria = 'norma', deteccion = 'auto', descripcion = 'Norma de sistemas de gestión ambiental.', variantes = '{}'::text[]
 where slug = 'iso-14001' and nombre = 'ISO 14001' and area = 'calidad_seguridad' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Norma de sistemas de gestión ambiental.' and variantes = array['ISO 14001:2015']::text[];
update public.competencias set nombre = 'ISO 27001', area = 'calidad_seguridad', categoria = 'norma', deteccion = 'auto', descripcion = 'Norma de gestión de la seguridad de la información.', variantes = array['ISO/IEC 27001']::text[]
 where slug = 'iso-27001' and nombre = 'ISO 27001' and area = 'calidad_seguridad' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Norma de gestión de la seguridad de la información.' and variantes = array['ISO/IEC 27001', 'ISO 27001:2022']::text[];
update public.competencias set nombre = 'ISO 45001', area = 'calidad_seguridad', categoria = 'norma', deteccion = 'auto', descripcion = 'Norma de sistemas de gestión de seguridad y salud en el trabajo.', variantes = '{}'::text[]
 where slug = 'iso-45001' and nombre = 'ISO 45001' and area = 'calidad_seguridad' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Norma de sistemas de gestión de seguridad y salud en el trabajo.' and variantes = array['ISO 45001:2018']::text[];
update public.competencias set nombre = 'ISO 9001', area = 'calidad_seguridad', categoria = 'norma', deteccion = 'auto', descripcion = 'Norma de sistemas de gestión de la calidad.', variantes = '{}'::text[]
 where slug = 'iso-9001' and nombre = 'ISO 9001' and area = 'calidad_seguridad' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Norma de sistemas de gestión de la calidad.' and variantes = array['ISO 9001:2015']::text[];
update public.competencias set nombre = 'Modelos de lenguaje (LLM)', area = 'ia', categoria = 'conocimiento', deteccion = 'auto', descripcion = 'Modelos de lenguaje de gran tamaño (LLM) y su uso en aplicaciones.', variantes = array['LLM', 'LLMs', 'large language models', 'modelos de lenguaje', 'modelos de lenguaje grandes']::text[]
 where slug = 'llm' and nombre = 'IA generativa y LLM' and area = 'ia' and categoria = 'conocimiento' and deteccion = 'auto' and descripcion = 'Modelos de lenguaje y herramientas de IA generativa.' and variantes = array['LLM', 'LLMs', 'modelos de lenguaje', 'large language models', 'IA generativa', 'inteligencia artificial generativa']::text[];
update public.competencias set nombre = 'Procedimiento escrito de trabajo seguro (PETS)', area = 'calidad_seguridad', categoria = 'actividad', deteccion = 'auto', descripcion = 'Procedimientos escritos para ejecutar tareas de forma segura.', variantes = array['procedimiento escrito de trabajo seguro', 'procedimientos escritos de trabajo seguro']::text[]
 where slug = 'pets' and nombre = 'Procedimiento escrito de trabajo seguro (PETS)' and area = 'calidad_seguridad' and categoria = 'metodologia' and deteccion = 'auto' and descripcion = 'Procedimientos escritos para ejecutar tareas de forma segura.' and variantes = array['procedimiento escrito de trabajo seguro', 'procedimientos escritos de trabajo seguro']::text[];
update public.competencias set nombre = 'PMBOK', area = 'gestion_proyectos', categoria = 'metodologia', deteccion = 'auto', descripcion = 'Guía de buenas prácticas de dirección de proyectos del PMI.', variantes = array['Guía del PMBOK', 'PMBOK Guide']::text[]
 where slug = 'pmbok' and nombre = 'PMBOK' and area = 'gestion_proyectos' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Guía de buenas prácticas de dirección de proyectos del PMI.' and variantes = array['Guía del PMBOK', 'PMBOK Guide']::text[];
update public.competencias set nombre = 'R (lenguaje estadístico)', area = 'datos_analisis', categoria = 'herramienta', deteccion = 'auto', descripcion = 'Lenguaje de programación orientado al análisis estadístico, la visualización y la ciencia de datos.', variantes = array['R', 'lenguaje R', 'programación en R']::text[]
 where slug = 'r' and nombre = 'R (lenguaje estadístico)' and area = 'datos_analisis' and categoria = 'herramienta' and deteccion = 'auto' and descripcion = 'Lenguaje y entorno para estadística y ciencia de datos (RStudio).' and variantes = array['R', 'lenguaje R', 'programación en R']::text[];
delete from public.competencias c where c.slug = 'html-css' and not exists (select 1 from public.oferta_requisitos r where r.competencia_id = c.id);
update public.competencias set estado = 'inactiva' where slug = 'html-css';   -- solo si alguna oferta ya la usa: queda oculta, no se borra

-- Cada competencia es UNA línea: para quitar una, borra su línea completa (no se rompe nada).

-- datos_analisis

-- programacion

-- ia

-- cad_bim

-- gestion_proyectos

-- calidad_seguridad

-- sistemas_empresariales

-- Las 18 que nacieron de SEPARAR lo que no era sinónimo (revisión de Harry, 10 nov 2026).
-- Cada competencia es UNA línea: para quitar una, borra su línea completa (no se rompe nada).

-- SAP: se suman las variantes de módulos (sin duplicar si se repite)
update public.competencias
   set variantes = (select coalesce(array_agg(distinct v order by v), '{}'::text[]) from unnest(variantes || array['SAP ERP', 'SAP MM', 'SAP PP', 'SAP PM', 'SAP FI', 'SAP S/4HANA']::text[]) as v)
 where slug = 'sap';

commit;

-- Comprobación final ------------------------------------------------------------------------------------------------
select
  (select count(*) from public.competencias)                                                                         as competencias,
  (select count(*) from public.competencias where categoria is null)                                                  as sin_categoria_debe_ser_0,
  (select count(*) from public.competencias where deteccion = 'revisar')                                              as en_revision,
  (select string_agg(area || '=' || n, ', ' order by area) from (select area, count(*) n from public.competencias group by area) x) as por_area,
  (select count(*) from (select lower(t) from public.competencias c, unnest(array[c.nombre] || c.variantes) as t
                          where c.estado = 'activa' group by lower(t) having count(distinct c.slug) > 1) x)           as terminos_repetidos_debe_ser_0,
  (select count(*) from public.competencias where (slug = 'analisis-trabajo-seguro' and nombre = 'Análisis de trabajo seguro (ATS)' and area = 'calidad_seguridad' and categoria = 'metodologia' and deteccion = 'auto' and descripcion = 'Análisis de los pasos y riesgos de una tarea antes de hacerla.' and variantes = array['análisis de trabajo seguro']::text[]) or (slug = 'ci-cd' and nombre = 'CI/CD' and area = 'programacion' and categoria = 'metodologia' and deteccion = 'auto' and descripcion = 'Integración y entrega continuas automatizadas.' and variantes = array['integración continua', 'despliegue continuo', 'entrega continua']::text[]) or (slug = 'git' and nombre = 'Git y GitHub' and area = 'programacion' and categoria = 'herramienta' and deteccion = 'auto' and descripcion = 'Control de versiones y trabajo colaborativo con repositorios.' and variantes = array['Git', 'GitHub']::text[]) or (slug = 'iperc' and nombre = 'IPERC' and area = 'calidad_seguridad' and categoria = 'metodologia' and deteccion = 'auto' and descripcion = 'Identificación de peligros, evaluación de riesgos y controles.' and variantes = array['matriz IPERC', 'identificación de peligros y evaluación de riesgos']::text[]) or (slug = 'iso-14001' and nombre = 'ISO 14001' and area = 'calidad_seguridad' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Norma de sistemas de gestión ambiental.' and variantes = array['ISO 14001:2015']::text[]) or (slug = 'iso-27001' and nombre = 'ISO 27001' and area = 'calidad_seguridad' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Norma de gestión de la seguridad de la información.' and variantes = array['ISO/IEC 27001', 'ISO 27001:2022']::text[]) or (slug = 'iso-45001' and nombre = 'ISO 45001' and area = 'calidad_seguridad' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Norma de sistemas de gestión de seguridad y salud en el trabajo.' and variantes = array['ISO 45001:2018']::text[]) or (slug = 'iso-9001' and nombre = 'ISO 9001' and area = 'calidad_seguridad' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Norma de sistemas de gestión de la calidad.' and variantes = array['ISO 9001:2015']::text[]) or (slug = 'llm' and nombre = 'IA generativa y LLM' and area = 'ia' and categoria = 'conocimiento' and deteccion = 'auto' and descripcion = 'Modelos de lenguaje y herramientas de IA generativa.' and variantes = array['LLM', 'LLMs', 'modelos de lenguaje', 'large language models', 'IA generativa', 'inteligencia artificial generativa']::text[]) or (slug = 'pets' and nombre = 'Procedimiento escrito de trabajo seguro (PETS)' and area = 'calidad_seguridad' and categoria = 'metodologia' and deteccion = 'auto' and descripcion = 'Procedimientos escritos para ejecutar tareas de forma segura.' and variantes = array['procedimiento escrito de trabajo seguro', 'procedimientos escritos de trabajo seguro']::text[]) or (slug = 'pmbok' and nombre = 'PMBOK' and area = 'gestion_proyectos' and categoria = 'norma' and deteccion = 'auto' and descripcion = 'Guía de buenas prácticas de dirección de proyectos del PMI.' and variantes = array['Guía del PMBOK', 'PMBOK Guide']::text[]) or (slug = 'r' and nombre = 'R (lenguaje estadístico)' and area = 'datos_analisis' and categoria = 'herramienta' and deteccion = 'auto' and descripcion = 'Lenguaje y entorno para estadística y ciencia de datos (RStudio).' and variantes = array['R', 'lenguaje R', 'programación en R']::text[]) or (slug = 'html-css' and estado = 'activa'))                                                 as filas_de_la_version_anterior_sin_corregir_debe_ser_0,
  has_table_privilege('anon', 'public.competencias', 'select')                                                        as anon_lee,
  has_table_privilege('anon', 'public.competencias', 'insert') or has_table_privilege('authenticated', 'public.competencias', 'update') as alguien_escribe_debe_ser_false;
